import OP from '../core';
import * as ops from '../lib/taskOps';
import Field from './Field';
import Icon from './Icon';
import type { CxUnit, Project, Task } from '../types';
import { UNITS } from '../lib/construction/catalogue';
import { durationOf, locationName } from '../lib/construction/plan';

const U = OP.util;
const UNIT_KEYS = Object.keys(UNITS) as CxUnit[];
const numText = (v: number | null | undefined) => (v == null ? '' : String(v));

// Task details for an activity generated by the building-plan workflow: where it is, its quantity basis and
// who is responsible. Values belong to this task only; other floors and the catalogue are not touched.
export default function ConstructionPanel({ p, t, edit }: { p: Project; t: Task; edit: (fn: (t: Task, p: Project) => void | false) => boolean }) {
  const c = t.construction, pc = p.construction;
  if (!c || !pc) return null;
  const loc = c.locationId ? locationName(pc.locations, c.locationId) : pc.buildings.find(b => b.id === c.buildingId)?.name || '';
  const act = c.activityKey ? pc.activities.find(a => a.key === c.activityKey) : undefined;
  const meta = (fn: (m: NonNullable<Task['construction']>) => void) => edit(x => { if (!x.construction) return false; fn(x.construction); });
  const head = <div className="section-title">Construction{c.dependencyReview === 'needs-review' && <span className="cx-tag warn">Needs dependency review</span>}</div>;
  if (c.role !== 'activity') {
    return <>{head}<div className="muted small">{c.role === 'building' ? 'Building' : c.role === 'location' ? 'Location' : 'Split by zone — quantities are on the zone tasks below it'}: {loc}</div></>;
  }
  const num = (v: string) => { const s = v.replace(/,/g, '').trim(); if (!s) return null; const n = Number(s); return isFinite(n) && n >= 0 ? n : undefined; };
  const suggestion = c.durationMode === 'quantity'
    ? durationOf({ mode: 'quantity', quantity: numText(c.quantity), productivity: numText(c.productivity), unit: c.unit || '', duration: '', contractor: '', crew: '', engineerId: '', notes: '' }, t.milestone)
    : null;
  const contractor = pc.contractors.find(x => x.id === c.contractorId);
  const crew = c.crewResourceUid ? p.resources.find(r => r.uid === c.crewResourceUid) : undefined;
  return (
    <>
      {head}
      <div className="cx-facts small">
        <span>Location</span><b>{loc}</b>
        <span>Activity type</span><b>{act?.name || c.activityKey}{act?.custom ? ' (custom)' : ''}</b>
        {c.engineer && <><span>Responsible engineer</span><b>{c.engineer.name}</b></>}
        {crew && <><span>Crew</span><b>{crew.name} (resource)</b></>}
      </div>
      {!t.milestone && <>
        <div className="row3">
          <label className="field"><span>Quantity</span>
            <Field className="inp" inputMode="decimal" value={numText(c.quantity)} onCommit={v => { const n = num(v); if (n === undefined) return false; meta(m => { m.quantity = n; }); }} />
          </label>
          <label className="field"><span>Unit</span>
            <select className="sel" value={c.unit || ''} onChange={e => meta(m => { m.unit = e.target.value as CxUnit | ''; })}>
              <option value="">—</option>{UNIT_KEYS.map(u => <option key={u} value={u}>{UNITS[u].label}</option>)}
            </select>
          </label>
          <label className="field"><span>Output / crew day</span>
            <Field className="inp" inputMode="decimal" value={numText(c.productivity)} onCommit={v => { const n = num(v); if (n === undefined) return false; meta(m => { m.productivity = n; }); }} />
          </label>
        </div>
        <div className="row2">
          <label className="field"><span>Duration basis</span>
            <select className="sel" value={c.durationMode || 'manual'} onChange={e => meta(m => { m.durationMode = e.target.value as 'manual' | 'quantity'; })}>
              <option value="quantity">Quantity ÷ output</option><option value="manual">Manual</option>
            </select>
          </label>
          <label className="field"><span>Contractor</span>
            <Field className="inp" list="cx-panel-contractors" value={contractor?.name || ''} onCommit={v => {
              const name = v.trim();
              edit((x, pp) => {
                if (!x.construction || !pp.construction) return false;
                if (!name) { delete x.construction.contractorId; return; }
                let k = pp.construction.contractors.find(o => o.name.toLowerCase() === name.toLowerCase());
                if (!k) { let n = pp.construction.contractors.length + 1; while (pp.construction.contractors.some(o => o.id === 'con-' + n)) n++; k = { id: 'con-' + n, name }; pp.construction.contractors.push(k); }
                x.construction.contractorId = k.id;
              });
            }} />
            <datalist id="cx-panel-contractors">{pc.contractors.map(k => <option key={k.id} value={k.name} />)}</datalist>
          </label>
        </div>
        {c.durationMode === 'quantity' && suggestion && (suggestion.ok
          ? <div className="cx-suggest small">
              <span>{suggestion.calc}</span>
              {Math.abs(suggestion.days - t.duration) > 1e-9
                ? <button className="btn" onClick={() => edit((x, pp) => { ops.setDuration(pp, x, suggestion.days); })}>Use {U.num(suggestion.days, 2)}d</button>
                : <span className="muted">Matches the duration.</span>}
            </div>
          : <div className="muted small">Enter a quantity, unit and output to work out the duration. Changing them never changes the duration on its own.</div>)}
      </>}
      {c.dependencyReview && c.dependencyReview !== 'reviewed' && (
        <div className="cx-suggest small">
          <span>{c.dependencyReview === 'needs-review' ? 'The template has no safe default predecessor for this activity.' : 'Predecessors were proposed by the template.'}
            {(c.proposedLinks || []).map((l, k) => <span key={k} className="muted"> {l.reason}</span>)}</span>
          <button className="btn" onClick={() => meta(m => { m.dependencyReview = 'reviewed'; })}><Icon name="check" />Mark links reviewed</button>
        </div>
      )}
      {c.dependencyReview === 'reviewed' && <div className="muted small">Links marked reviewed. This is a planning note, not an approval of the plan.</div>}
    </>
  );
}
